-- 100 spell_dbc rows for a second, parallel bonus on the SAME elite/rare
-- kill tiers/counter as kt_elite_bonus_spells.sql (901400-901499) —
-- kill_milestones.cpp, GrantEliteAccuracyBonusIfReached. Each row is an
-- INDEPENDENT +3% spell (accumulated one at a time, total = 3%*N at N
-- tiers). TWO effects per spell: Effect_1 = SPELL_AURA_MOD_HIT_CHANCE (54)
-- — on this core, a single aura covers both melee and ranged hit chance
-- (AuraEffect::HandleModHitChance updates both m_modMeleeHitChance and
-- m_modRangedHitChance); Effect_2 = SPELL_AURA_MOD_SPELL_HIT_CHANCE (55) —
-- spell hit chance, separately. Attributes=64 = SPELL_ATTR0_PASSIVE.
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 901500 AND 901599;
